import numpy as np
import cv2

# 1. Define dimensions (Width * Height must equal 2560000 for grayscale)
width = 429 
height = 78

# 2. Read the hex file generated by Vivado
txt_path = "/mnt/d/College/Projects/VLSI_Project/Softwares/output/vivado/Hari4.txt"
pixels = []

print("Reading simulation output file...")
with open(txt_path, "r") as file:
    for line in file:
        clean_line = line.strip()
        if clean_line: # Ensure line is not empty
            # Convert hex string to integer
            pixels.append(int(clean_line, 16))

# 3. Convert the list into a NumPy array
pixel_array = np.array(pixels, dtype=np.uint8)

# 4. Reshape the flat 1D array into a 2D image matrix
try:
    image = pixel_array.reshape((height, width))
    
    # 5. Save the image using OpenCV
    output_path = "/mnt/d/College/Projects/VLSI_Project/Softwares/output/python/hari7vivado.jpeg"
    cv2.imwrite(output_path, image)
    print(f"Success! Image successfully saved to: {output_path}")

except ValueError as e:
    print(f"Error reshaping array: {e}")
    print(f"Total pixels read: {len(pixel_array)}. Ensure height * width matches this number.")
